    def test_bulk_structural_writes_are_rejected(self) -> None:
        """Use case: Bulk operations bypass model save hooks.
        Expected result: Structural writes fail while bulk renaming remains available.
        """
        # 1. Create a valid folder through the normal model lifecycle.
        node = FileNode.objects.create(kind="FOLDER", name="Root")
        # 2. Reject update, bulk_update, and bulk_create bypasses.
        with self.assertRaises(ValueError):
            FileNode.objects.filter(pk=node.pk).update(parent=node)
        node.parent = node
        with self.assertRaises(ValueError):
            FileNode.objects.bulk_update([node], ["parent"])
        with self.assertRaises(ValueError):
            FileNode.objects.bulk_create([FileNode(kind="FOLDER", name="Other")])
        # 3. Allow unrelated metadata updates.
        self.assertEqual(FileNode.objects.filter(pk=node.pk).update(name="Renamed"), 1)

    def test_database_constraints_reject_invalid_shapes(self) -> None:
        """Use case: A low-level write bypasses Python validation.
        Expected result: Database checks reject invalid kind/content pairs and self-parenting.
        """
        # 1. Exercise SQL constraints independently of the custom manager and save hook.
        for kind, content in (
            ("FILE", ""),
            ("FILE", None),
            ("FOLDER", "bytes.txt"),
            ("INVALID", ""),
        ):
            with (
                self.subTest(kind=kind, content=content),
                self.assertRaises(IntegrityError),
                transaction.atomic(),
            ):
                models.Model.save(
                    FileNode(name="Invalid", kind=kind, content=content),
                    force_insert=True,
                )
        # 2. Reject a direct self-parent link at the database boundary.
        node = FileNode.objects.create(kind="FOLDER", name="Root")
        with self.assertRaises(IntegrityError), transaction.atomic():
            FileNode._base_manager.filter(pk=node.pk).update(parent_id=node.pk)

    def prepare_legacy_migration(self) -> None:
        """Use historical model classes so source fixtures bypass modern save hooks."""
        self.migration = import_module(
            "bloomerp.migrations.0086_file_nodes_and_object_references"
        )
        self.historical_apps = ProjectState.from_apps(apps).apps
        self.legacy_file_model = self.historical_apps.get_model("bloomerp", "File")
        self.enterContext(
            patch.object(
                self.legacy_file_model._meta.get_field("file"), "storage", self.storage
            )
        )
        self.template = self.historical_apps.get_model(
            "bloomerp", "DocumentTemplate"
        ).objects.create(name="Contract")
        self.template_type, _ = ContentType.objects.get_or_create(
            app_label="bloomerp", model="documenttemplate"
        )
        self.todo_type = ContentType.objects.get_for_model(Todo)

    def run_legacy_migration(self) -> None:
        """Run the migration twice while rejecting binary reads, writes, or deletions."""
        with (
            patch.object(
                self.storage,
                "open",
                side_effect=AssertionError("Migration read file bytes"),
            ),
            patch.object(
                self.storage,
                "save",
                side_effect=AssertionError("Migration rewrote storage"),
            ),
            patch.object(
                self.storage,
                "delete",
                side_effect=AssertionError("Migration deleted storage"),
            ),
        ):
            self.migration.migrate_files(
                self.historical_apps, connection.schema_editor()
            )
            self.migration.migrate_files(
                self.historical_apps, connection.schema_editor()
            )

    def migrate_legacy_document(self) -> FileNode:
        """Ignore legacy folders while preserving a document and its recorded owners."""
        self.prepare_legacy_migration()
        folder_model = self.historical_apps.get_model("bloomerp", "FileFolder")
        generated = folder_model.objects.create(
            name="Generated object folder",
            kind="object",
            scope_key="migration-test",
            protected=True,
        )
        manual = folder_model.objects.create(name="Signed contracts", parent=generated)
        self.first_todo = Todo.objects.create(title="Direct owner")
        self.second_todo = Todo.objects.create(title="Editor owner")
        self.legacy_meta = {
            "document_template": {
                "id": str(self.template.pk),
                "name": self.template.name,
            },
            "signature": {"signed": False, "signed_file_id": str(uuid4())},
        }
        self.storage.save("legacy/generated.pdf", ContentFile(b"original document"))
        self.legacy_file = self.legacy_file_model.objects.create(
            name="Contract",
            file="legacy/generated.pdf",
            folder=manual,
            persisted=True,
            content_type_id=self.todo_type.pk,
            object_id=str(self.first_todo.pk),
            meta=self.legacy_meta,
        )
        field, _ = self.historical_apps.get_model(
            "bloomerp", "ApplicationField"
        ).objects.get_or_create(
            content_type_id=self.todo_type.pk,
            field="content",
            defaults={"field_type": "text"},
        )
        self.occurrences = [uuid4(), uuid4()]
        for occurrence in self.occurrences:
            self.historical_apps.get_model(
                "bloomerp", "FileFieldReference"
            ).objects.create(
                file=self.legacy_file,
                application_field=field,
                object_id=str(self.second_todo.pk),
                occurrence_id=occurrence,
            )
        self.run_legacy_migration()
        return FileNode.objects.get(pk=self.legacy_file.pk)

    def migrate_template_only(self, shape: str) -> FileNode:
        """Migrate older template metadata without inventing unrecorded object inputs."""
        self.prepare_legacy_migration()
        meta = (
            {
                "document_template_id": str(self.template.pk),
                "document_template_name": "Contract",
            }
            if shape == "flat"
            else {"document_template": str(self.template.pk)}
        )
        self.storage.save("legacy/template.pdf", ContentFile(b"document"))
        file = self.legacy_file_model.objects.create(
            name="Document",
            file="legacy/template.pdf",
            meta=meta,
            content_type_id=self.template_type.pk,
            object_id=str(self.template.pk),
            persisted=True,
        )
        self.run_legacy_migration()
        return FileNode.objects.get(pk=file.pk)

    def test_file_migration_rolls_back_on_invalid_source(self) -> None:
        """Use case: A legacy file names a document template that no longer exists.
        Expected result: The entire copy rolls back and legacy files and bytes survive.
        """
        # 1. Seed valid bytes with dangling provenance through a historical model.
        self.prepare_legacy_migration()
        self.storage.save("legacy/orphan.pdf", ContentFile(b"keep me"))
        source = self.legacy_file_model.objects.create(
            name="Orphan",
            file="legacy/orphan.pdf",
            meta={"document_template_id": str(uuid4())},
        )
        # 2. Fail the additive migration before accepting incomplete references.
        with self.assertRaisesRegex(RuntimeError, "Missing legacy file target"):
            self.migration.migrate_files(
                self.historical_apps, connection.schema_editor()
            )
        # 3. Retain the source and storage while rolling back the copied node.
        self.assertFalse(FileNode.objects.filter(pk=source.pk).exists())
        self.assertTrue(self.legacy_file_model.objects.filter(pk=source.pk).exists())
        self.assertEqual(self.storage.open(source.file.name).read(), b"keep me")

    def test_file_migration_rejects_node_collision(self) -> None:
        """Use case: A new node occupies a legacy UUID with different content.
        Expected result: Migration refuses to overwrite either record or stored file.
        """
        # 1. Seed a source and an unrelated new node sharing its UUID.
        self.prepare_legacy_migration()
        self.storage.save("legacy/source.txt", ContentFile(b"source"))
        source = self.legacy_file_model.objects.create(
            name="Source", file="legacy/source.txt"
        )
        FileNode.objects.create(
            pk=source.pk, name="Other", kind="FILE", content="other.txt"
        )
        # 2. Detect the collision explicitly.
        with self.assertRaisesRegex(RuntimeError, "migration conflict"):
            self.migration.migrate_files(
                self.historical_apps, connection.schema_editor()
            )
        # 3. Preserve the already existing node.
        self.assertEqual(FileNode.objects.get(pk=source.pk).content.name, "other.txt")

